import React, { useEffect, useState } from 'react';
import solutions from './solutions';
import javaSolutions from './javaSolutions';
import styles from './Dsa.module.css';

// Render tokens as React text nodes, so solution code is never interpreted as HTML.
const tokenPattern = /(\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:public|private|static|final|class|return|if|else|for|while|break|continue|new|null|true|false|int|boolean|char|void|instanceof)\b|\b(?:String|StringBuilder|List|ArrayList|Map|HashMap|Set|HashSet|Arrays|Collections|Comparator|Integer|Math|Character|Locale|ListNode)\b|\b\d+\b)/g;
const keywords = /^(public|private|static|final|class|return|if|else|for|while|break|continue|new|null|true|false|int|boolean|char|void|instanceof)$/;
const types = /^(String|StringBuilder|List|ArrayList|Map|HashMap|Set|HashSet|Arrays|Collections|Comparator|Integer|Math|Character|Locale|ListNode)$/;
function highlightedCode(code) {
  return code.split(tokenPattern).map((part, index) => {
    let kind;
    if (part.startsWith('//') || part.startsWith('/*')) kind = 'comment';
    else if (part.startsWith('"') || part.startsWith("'")) kind = 'string';
    else if (keywords.test(part)) kind = 'keyword';
    else if (types.test(part)) kind = 'type';
    else if (/^\d+$/.test(part)) kind = 'literal';
    return kind ? <span className={styles[kind]} key={index}>{part}</span> : part;
  });
}

function Solution({ label, time, space, code }) {
  const annotatedCode = `// Time: ${time}\n// Space: ${space}\n${code}`;
  return <section className={styles.solution}>
    <div className={styles.solutionHeader}><h3>{label}</h3><span>Time: {time} · Space: {space}</span></div>
    <pre><code>{highlightedCode(annotatedCode)}</code></pre>
  </section>;
}

export default function Dsa() {
  const [query, setQuery] = useState('');
  const [openProblem, setOpenProblem] = useState(null);
  useEffect(() => {
    document.title = 'DSA Solutions | Paras Jain';
    const robots = document.querySelector('meta[name="robots"]');
    if (robots) robots.content = 'noindex,nofollow';
  }, []);
  const filtered = solutions.filter(([number, title, difficulty, , , , , category]) =>
    `${number} ${title} ${difficulty} ${category}`.toLowerCase().includes(query.toLowerCase().trim())
  );
  const categories = [...new Set(solutions.map(problem => problem[7]))];
  return <main className={styles.page}>
    <div className={styles.container}>
      <header className={styles.header}><h1>DSA solutions</h1><span>Java · {solutions.length} problems</span></header>
      <label className={styles.search}><span>Search problems</span><input type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Search by name, number, difficulty or category" /></label>
      <p className={styles.hint}>{filtered.length} of {solutions.length} problems · Methods use <code>java.util.*</code>; linked lists use LeetCode’s <code>ListNode</code>. Complexity uses n for input length (or text length), m for the second input or pattern length, and k for maximum word length. Space includes returned output where indicated.</p>
      <div className={styles.categories}>
        {categories.map(category => {
          const problems = filtered.filter(problem => problem[7] === category);
          if (!problems.length) return null;
          return <details className={styles.category} key={category} open>
            <summary className={styles.categoryHeader}><h2>{category}</h2><span>{problems.length} {problems.length === 1 ? 'problem' : 'problems'}</span><span className={styles.categoryToggle} aria-hidden="true">⌄</span></summary>
            <div className={styles.list}>
              {problems.map(([number, title, difficulty, bruteTime, optimizedTime, bruteSpace, optimizedSpace]) => <details className={styles.card} key={number} open={openProblem === number}>
                <summary onClick={event => {
                  event.preventDefault();
                  setOpenProblem(current => current === number ? null : number);
                }}><span className={styles.number}>#{number}</span><span className={styles.title}>{title}</span><span className={`${styles.difficulty} ${styles[difficulty.toLowerCase()]}`}>{difficulty}</span><span className={styles.plus} aria-hidden="true">+</span></summary>
                <div className={styles.solutions}>
                  <Solution label="Brute force" time={bruteTime} space={bruteSpace} code={javaSolutions[number][0]} />
                  <Solution label="Optimized" time={optimizedTime} space={optimizedSpace} code={javaSolutions[number][1]} />
                </div>
              </details>)}
            </div>
          </details>;
        })}
        {!filtered.length && <p className={styles.empty}>No problems found. Try another search.</p>}
      </div>
    </div>
  </main>;
}
